import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
        padding: '20px',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      <JxDivider label={steps[step].label} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField label="Город" value={city} onChange={(event) => setCity(event.target.value)} />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', color: 'var(--jx-text-2)' }}>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Имя:</strong> {fullName || '—'}
          </p>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Почта:</strong> {email || '—'}
          </p>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Телефон:</strong> {phone || '—'}
          </p>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Адрес:</strong> {address || '—'}
          </p>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Город:</strong> {city || '—'}
          </p>
          <p style={{ margin: 0 }}>
            <strong style={{ color: 'var(--jx-text)' }}>Индекс:</strong> {postalCode || '—'}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

